EN3 = {
"umeni-01": ("How many centimetres tall is Michelangelo's statue of David in Florence?", "centimetre|centimetres", "Michelangelo's David stands 517 cm, over five metres tall. He carved it in 1501–1504 from a single block of marble that two other artists had already tried and failed to work.", "Statue height 5.17 m per the Wikipedia infobox."),
"umeni-02": ("How many million dollars did Salvator Mundi, attributed to Leonardo da Vinci, sell for at auction in 2017 (including buyer's premium)?", "million dollars|million dollars", "Salvator Mundi sold at Christie's in New York on 15 November 2017 for $450,312,500, still the highest price ever paid for a painting at auction. In 1958 the same picture had sold as a copy for just £45.", "$450,312,500 including buyer's premium (hammer price $400 million), Christie's New York, 15 Nov 2017."),
"umeni-03": ("How many towers will the completed Sagrada Família basilica in Barcelona have according to Gaudí's design?", "tower|towers", "Gaudí designed 18 towers: twelve for the apostles, four for the evangelists, one for the Virgin Mary and the tallest, 172.5 metres, for Jesus Christ. The foundation stone was laid back in 1882.", "Number of towers in Gaudí's design (12 apostles + 4 evangelists + Virgin Mary + Jesus Christ)."),
"umeni-04": ("How many years did it take to build St. Vitus Cathedral at Prague Castle, from the foundation stone to completion?", "year|years", "John of Luxembourg laid the cathedral's foundation stone in 1344; it was finished only in September 1929 under President Masaryk. Construction took 585 years and spanned Gothic, Baroque and Neo-Gothic.", "From the foundation stone on 21 Nov 1344 to completion and consecration on 28 Sept 1929."),
"umeni-05": ("How many centimetres wide is Leonardo's mural The Last Supper in Milan?", "centimetre|centimetres", "The Last Supper isn't a canvas: Leonardo painted it in 1495–1498 straight onto the refectory wall of Santa Maria delle Grazie in Milan. It measures 460 × 880 cm, so the apostles are almost life-size.", "Painting dimensions 460 × 880 cm (height × width)."),
"umeni-06": ("How many million dollars was the Mona Lisa valued at for insurance when it travelled to an exhibition in the USA in 1962, according to Guinness World Records?", "million dollars|million dollars", "When the Mona Lisa travelled from the Louvre to Washington and New York in December 1962 it was valued at $100 million for insurance. According to Guinness World Records that is still the highest insurance valuation of any painting.", "Insurance valuation as of 14 Dec 1962 (Guinness World Records)."),
"umeni-07": ("How many francs did Vincent van Gogh sell The Red Vineyard for in 1890 – the only painting he is documented to have sold in his lifetime?", "franc|francs", "Belgian painter Anna Boch bought The Red Vineyard at an exhibition in Brussels in 1890 for 400 francs. It now hangs in the Pushkin Museum in Moscow and is the only painting known for certain to have been sold in Van Gogh's lifetime.", "Sold at the Les XX exhibition in Brussels, 1890."),
"umeni-08": ("How many windows does the crown of the Statue of Liberty in New York have?", "window|windows", "The Statue of Liberty's crown has 7 rays and 25 windows through which visitors look out over New York Harbor. From the ground to the tip of the torch the statue is almost 93 metres tall.", "National Park Service figure."),
"umeni-09": ("How many paintings and designs did Pablo Picasso produce in his 75-year career, according to Guinness World Records?", "painting|paintings", "Guinness World Records lists Picasso as the most prolific painter in history: about 13,500 paintings and designs, 100,000 prints and engravings, 34,000 book illustrations and 300 sculptures and ceramics.", "Guinness World Records estimate ('about 13,500 paintings and designs')."),
"umeni-10": ("How many tonnes of paint does one complete repainting of the Eiffel Tower use?", "tonne|tonnes", "To keep the Eiffel Tower from rusting it is repainted roughly every 7 years, using 60 tonnes of paint each time. There's plenty to cover: 18,038 metal parts held together by 2.5 million rivets.", "Wikipedia (EN) figure: 60 tonnes of paint every 7 years."),
"umeni-11": ("How many centimetres tall is the Mona Lisa?", "centimetre|centimetres", "The Mona Lisa is surprisingly small: just 77 × 53 cm, painted on a poplar panel. Over 20,000 people see it at the Louvre every day, mostly over a sea of heads and phones.", "Height × width: 77 × 53 cm."),
"umeni-12": ("How many metres tall is the Burj Khalifa in Dubai, the world's tallest building (architectural height including spire)?", "metre|metres", "The Burj Khalifa is 828 metres tall with 163 floors. Its lifts travel at 10 m/s, so you reach the observation deck on the 124th floor in a minute.", "Including spire, excluding antenna; total height 829.8 m."),
"umeni-13": ("How many metres tall is the Christ the Redeemer statue in Rio de Janeiro (excluding the pedestal)?", "metre|metres", "Christ the Redeemer is 30 metres tall (plus an 8-metre pedestal) and its outstretched arms span 28 metres. It is reinforced concrete clad in soapstone and gets struck by lightning several times a year.", "Excluding the 8 m pedestal."),
"umeni-14": ("How many million dollars did Ronald Lauder pay in 2006 for Klimt's Portrait of Adele Bloch-Bauer I, then the most expensive painting in the world?", "million dollars|million dollars", "The 'Golden Adele' sold in 2006 for $135 million, a record at the time. Austria first had to hand it over to the original owner's heir – a story filmed with Helen Mirren as Woman in Gold.", "Private sale, June 2006."),
"umeni-15": ("How many metres tall are the Petronas Towers in Kuala Lumpur, the tallest twin towers in the world (rounded to whole metres)?", "metre|metres", "The Petronas Towers stand 451.9 m tall with 88 floors. They were the world's tallest building from 1998 to 2004; a 58-metre skybridge links them on the 41st floor.", "Exactly 451.9 m."),
"umeni-16": ("How many metres long is the Great Sphinx of Giza (from paw to tail)?", "metre|metres", "The Sphinx is 73 metres long and 20 metres high, carved from a single mass of limestone. Its nose has been missing since at least the 15th century.", ""),
"umeni-17": ("How many detective novels did Agatha Christie write?", "novel|novels", "Agatha Christie wrote 66 detective novels and 14 short-story collections, which have sold over two billion copies – only the Bible and Shakespeare have sold more.", ""),
"umeni-18": ("How many sonnets did William Shakespeare write?", "sonnet|sonnets", "Shakespeare wrote 154 sonnets, first published together in 1609. The first 126 are addressed to a young man, the rest to a mysterious 'Dark Lady'.", ""),
"veda-01": ("How many metres per second does light travel in a vacuum?", "metre|metres", "The speed of light in a vacuum is exactly 299,792,458 metres per second – and it isn't a measured value but a definition: since 1983 the metre itself has been defined from it.", "Exact defined value in the SI system (the definition of the metre has been based on it since 1983)."),
"veda-02": ("How many kilometres away is the Moon from the Earth on average?", "kilometre|kilometres", "The Moon is on average 384,400 kilometres away. According to NASA, about 30 Earth-sized planets would fit side by side in the gap.", "Average Earth–Moon distance according to NASA."),
"veda-03": ("How many metres deep is the deepest borehole in the world, the Kola Superdeep Borehole in Russia?", "metre|metres", "The Soviets drilled on the Kola Peninsula from 1970 and in 1989 reached a depth of 12,262 metres – more than the height of Mount Everest. The hole is just 23 centimetres across.", "Maximum depth reached by borehole SG-3 (1989)."),
"veda-04": ("How many metres deep is the Challenger Deep, the deepest point of the world's oceans, according to NOAA?", "metre|metres", "The deepest point in the ocean, the Challenger Deep in the Mariana Trench, lies 10,935 metres below the surface according to the US agency NOAA. If you sank Mount Everest there, more than two kilometres of water would remain above its summit.", "NOAA figure (given as approximate); other surveys differ by tens of metres."),
"veda-05": ("How many days did the longest single stay of a human in space (Valeri Polyakov's record on the Mir station) last?", "day|days", "Russian physician and cosmonaut Valeri Polyakov spent 437 days in a row on the Mir station (January 1994 to March 1995), orbiting the Earth over 7,000 times. The record for the longest single spaceflight still stands.", "Flight 8 Jan 1994 – 22 Mar 1995 (Soyuz TM-18 / Mir / Soyuz TM-20), 437 days 18 hours in total."),
"veda-06": ("How many kilograms of lunar rock and dust did the six Apollo missions bring back to Earth?", "kilogram|kilograms", "The astronauts of the six Apollo missions (1969–1972) brought back 382 kilograms of lunar rocks, core samples, pebbles, sand and dust – 2,200 separate samples from six different sites. NASA is still studying them.", "Total for all six Apollo landings (1969–1972)."),
"veda-07": ("How many Earth days does one rotation of Venus on its axis, i.e. one Venusian day, take?", "Earth day|Earth days", "Venus spins so lazily that one of its days lasts 243 Earth days – longer than its whole year, which takes just 225 days. It also spins backwards compared to Earth, so the Sun rises in the west.", "Rotation period of Venus according to NASA (243 Earth days); its orbit around the Sun takes 225 days."),
"veda-08": ("How many kilometres is the circumference of the Large Hadron Collider (LHC) ring at CERN?", "kilometre|kilometres", "The world's largest particle accelerator, the LHC at CERN near Geneva, is a 27-kilometre ring of superconducting magnets in a tunnel about 100 metres underground. The magnets are cooled to −271 °C, colder than outer space.", "CERN figure (27 km)."),
"veda-09": ("How many hexagonal segments make up the primary mirror of the James Webb Space Telescope?", "segment|segments", "Webb's 6.5-metre primary mirror consists of 18 hexagonal gold-coated beryllium segments. It wouldn't fit into any rocket in one piece, so it unfolded after launch in space.", ""),
"veda-10": ("How many orbits of the Earth does the International Space Station (ISS) complete in 24 hours?", "orbit|orbits", "The ISS travels at about 8 kilometres per second and circles the Earth roughly every 90 minutes – 16 orbits a day, giving the crew 16 sunrises and 16 sunsets.", "NASA figure."),
"veda-11": ("How many metres per second does sound travel through air at 20 °C?", "metre|metres", "Sound travels through 20 °C air at 343 m/s – covering a kilometre in just under three seconds. That's why we count the seconds between lightning and thunder.", "Standard tabulated value for dry air at 20 °C."),
"veda-12": ("How many Earth days does a year on Mars last?", "Earth day|Earth days", "A year on Mars lasts 687 Earth days, almost two of ours. A Martian day (sol), on the other hand, is very Earth-like at 24.6 hours.", ""),
"veda-13": ("How many times did Valentina Tereshkova orbit the Earth on her 1963 flight, when she became the first woman in space?", "orbit|orbits", "Tereshkova orbited the Earth 48 times in Vostok 6 in just under three days – more orbits than all the American astronauts before her put together.", "Vostok 6 flight, 16–19 June 1963."),
"veda-14": ("How many orbits of the Earth did Sputnik 1, the first artificial satellite, complete before burning up in the atmosphere in 1958?", "orbit|orbits", "Sputnik 1 was just 58 cm across and weighed 83.6 kg. In three months it completed 1,440 orbits of the Earth before burning up in the atmosphere in January 1958.", "Launched 4 Oct 1957, decayed 4 Jan 1958."),
"veda-15": ("How many chemical elements are known today (and listed in the periodic table)?", "element|elements", "We know 118 elements, which complete the first seven rows of the periodic table. Only the first 94 occur naturally on Earth; the rest were made in laboratories.", ""),
"veda-16": ("How many people have walked on the surface of the Moon so far?", "person|people", "Only 12 people have walked on the Moon, all during the six Apollo landings of 1969–1972. But 24 astronauts flew to the Moon – the rest stayed in orbit.", "As of 2026."),
"veda-17": ("How many kilograms does the Mars rover Curiosity weigh?", "kilogram|kilograms", "Curiosity weighs 899 kg – like a small car – and was lowered onto Mars on cables by a 'sky crane' in August 2012. It is still driving there today.", "Dry mass."),
"veda-18": ("How many centimetres is the diameter of the Hubble Space Telescope's primary mirror?", "centimetre|centimetres", "Hubble's mirror is 2.4 metres across and was ground wrong by two micrometres – it has only seen sharply since astronauts repaired it in 1993.", "2.4 m; launched 1990."),
"veda-19": ("How many minutes did Yuri Gagarin's flight, the first human spaceflight, last according to official figures?", "minute|minutes", "Gagarin's flight on 12 April 1961 officially lasted 108 minutes from launch to landing. Later analysis of documents showed it was two minutes shorter.", "Officially reported flight duration; some sources give 106 minutes."),
"veda-20": ("How many kilometres above sea level is the Kármán line, the internationally recognised boundary of space?", "kilometre|kilometres", "According to the FAI, space begins 100 km above sea level. That's closer than a lot of everyday journeys – space is nearer than most people think.", "FAI definition."),
"zemepis-01": ("How many metres is the maximum depth of Lake Baikal, the deepest lake in the world?", "metre|metres", "At 1,642 metres Baikal is the deepest lake on the planet and holds roughly a fifth of all the unfrozen fresh surface water on Earth.", ""),
"zemepis-02": ("How many metres tall is Angel Falls in Venezuela, the world's tallest uninterrupted waterfall?", "metre|metres", "Angel Falls drops from 979 metres – almost three Eiffel Towers stacked up. The uninterrupted plunge alone is 807 metres.", "Total height of the falls; plunge 807 m."),
"zemepis-03": ("How many countries does the Danube flow through or border?", "country|countries", "The Danube rises in Germany and on its 2,850 km journey to the Black Sea flows through or borders 10 countries – more than any other river in the world.", "Germany, Austria, Slovakia, Hungary, Croatia, Serbia, Romania, Bulgaria, Moldova and Ukraine."),
"zemepis-04": ("How many kilometres long is the Trans-Siberian Railway from Moscow to Vladivostok?", "kilometre|kilometres", "The Trans-Siberian is 9,289 km long and the longest railway line in the world. The journey from Moscow to Vladivostok without changing trains takes about a week.", "Main line Moscow – Vladivostok."),
"zemepis-05": ("How many kilometres long is the border between Canada and the United States, the longest international border in the world?", "kilometre|kilometres", "The Canada–US border is 8,891 km long including the Alaska section. It is the longest border between two countries in the world.", "Including the Alaska–Canada border."),
"zemepis-06": ("How many kilometres do all surviving sections of the Great Wall of China add up to, according to the 2012 Chinese survey (rounded to whole kilometres)?", "kilometre|kilometres", "The 2012 Chinese survey added up all the walls and trenches of the Great Wall to 21,196 km – about half the circumference of the Earth.", "Exactly 21,196.18 km according to the survey by China's National Cultural Heritage Administration (2012)."),
"zemepis-07": ("How many time zones does Russia have?", "time zone|time zones", "Russia spans 11 time zones – when they're having breakfast in Kaliningrad, it's dinner time in Vladivostok.", ""),
"zemepis-08": ("How many islands does Sweden have according to Statistics Sweden (2013 report)?", "island|islands", "According to the 2013 count Sweden has 267,570 islands, the most in the world. Fewer than a thousand are permanently inhabited.", "According to the Statistics Sweden report 'Coast, shores and islands in Sweden 2013'."),
"zemepis-09": ("How many kilometres is the Earth's circumference at the equator (rounded to whole kilometres)?", "kilometre|kilometres", "The equator is 40,075 km long. The circumference through the poles is 67 km shorter because the Earth is slightly flattened at the poles.", "Exactly 40,075.017 km."),
"zemepis-10": ("How many UN member states are in Africa?", "state|states", "Africa has 54 UN member states – more than any other continent. Add two states with limited recognition: Western Sahara and Somaliland.", "UN member states; 56 including the two partially recognised states."),
"zemepis-11": ("How many countries does China border by land?", "country|countries", "China has 14 land neighbours – from Russia and Mongolia through India and Pakistan to Vietnam. Its land border is over 20,000 km long.", "Afghanistan, Bhutan, Myanmar, India, North Korea, Kazakhstan, Kyrgyzstan, Pakistan, Laos, Mongolia, Nepal, Russia, Tajikistan, Vietnam."),
"zemepis-12": ("How many metres tall is Mount Everest according to the joint China–Nepal survey of 2020 (rounded to whole metres)?", "metre|metres", "Everest is 8,848.86 m, rounded 8,849 metres. Thanks to tectonic plate movement it is still growing – about 4 mm a year.", "Exactly 8,848.86 m (2020 survey)."),
"zemepis-13": ("How many languages does the Eighth Schedule of the Indian Constitution list as officially recognised ('scheduled languages')?", "language|languages", "India's constitution recognises 22 languages, including Hindi, Bengali, Tamil and Sanskrit. English isn't among them – the constitution treats it as a subsidiary official language.", ""),
"zemepis-14": ("How many kilometres long is the Panama Canal?", "kilometre|kilometres", "The Panama Canal is 82 km long and since opening in 1914 has cut ships' journeys between the oceans by around 13,000 km. Transit takes 8 to 10 hours.", ""),
"zemepis-15": ("How many time zones does France use including its overseas territories – more than any other country?", "time zone|time zones", "Thanks to overseas territories from Polynesia to Réunion, France uses 12 time zones, more than Russia or the USA. Counting its Antarctic claim it would be 13.", "Excluding the Antarctic claim."),
"zemepis-16": ("How many metres above sea level is Kilimanjaro, the highest mountain in Africa?", "metre|metres", "Kilimanjaro is 5,895 m and the highest free-standing mountain in the world – it rises 4,900 metres above the surrounding plain. There's a glacier on top, even though it stands 300 km from the equator.", ""),
"zemepis-17": ("How many square kilometres is Greenland, the largest island in the world?", "square kilometre|square kilometres", "Greenland covers 2,166,086 km², 27 times the size of Czechia, yet only about 57,000 people live there. Over 80% of it is covered by ice sheet.", ""),
"zemepis-18": ("How many metres is the maximum depth of Lake Tanganyika, the second deepest lake in the world?", "metre|metres", "Tanganyika in Africa is 1,470 metres deep and second only to Baikal in both volume and depth. It stretches 673 km – the longest freshwater lake in the world.", ""),
"zemepis-19": ("How many hectares is the area of Monaco (rounded to whole hectares)?", "hectare|hectares", "Monaco covers 2.08 km², i.e. 208 hectares – it would fit twice into New York's Central Park. Yet over 38,000 people live there.", "2.08 km² (after the 2024 expansion)."),
"zemepis-20": ("How many metres above sea level is Mount Fuji, the highest mountain in Japan (rounded to whole metres)?", "metre|metres", "Fuji is 3,776 metres tall and an active volcano – it last erupted in 1707. Over 200,000 people climb it every summer.", "Exactly 3,776.24 m."),
"zemepis-21": ("How many islands does Japan have according to the official 2023 count?", "island|islands", "Japan has 14,125 islands – the new 2023 count found twice as many as the previous one from 1987, because more accurate maps were used.", "2023 count by the Geospatial Information Authority of Japan."),
"zemepis-22": ("How many square kilometres is Russia, the largest country in the world?", "square kilometre|square kilometres", "Russia covers 17,098,246 km² – only Antarctica and the surface of Pluto are bigger. Czechia would fit into it 217 times.", "Within internationally recognised borders."),
"zemepis-23": ("How many metres long is the Danyang–Kunshan Grand Bridge in China, the longest bridge in the world?", "metre|metres", "The Danyang–Kunshan Grand Bridge on the Beijing–Shanghai high-speed line is 164.8 km long. Trains cross it in about half an hour.", "164.8 km."),
"zemepis-24": ("How many kilometres long is the Gotthard Base Tunnel in Switzerland, the longest railway tunnel in the world (rounded to whole kilometres)?", "kilometre|kilometres", "The Gotthard Base Tunnel is 57 km long and trains pass through it in 20 minutes. Construction took 17 years and 28 million tonnes of rock had to be excavated.", "Exactly 57.09 km."),
"zemepis-25": ("How many sovereign countries are there in South America?", "country|countries", "South America has 12 sovereign countries. Brazil borders all of them except Chile and Ecuador.", "Excluding dependent territories (French Guiana, Falklands)."),
"zvirata-01": ("How many puppies did Tia, a Neapolitan mastiff from England, have in 2004 – the largest litter ever recognised by Guinness World Records?", "puppy|puppies", "Tia, a Neapolitan mastiff from Cambridgeshire, gave birth to a round 24 puppies on 29 November 2004. Anyone who has looked after a single puppy can imagine the weeks that followed.", "According to Guinness World Records; litter born 29 Nov 2004, owners Damian Ward and Anne Kellegher."),
"zvirata-02": ("How many years did Creme Puff from Austin, Texas, the oldest cat ever according to Guinness World Records, live?", "year|years", "Creme Puff was born on 3 August 1967 and didn't leave until 6 August 2005 – aged 38 years and 3 days. She clearly didn't need nine lives; one really long one was enough.", "38 years and 3 days (3 Aug 1967 – 6 Aug 2005); completed years counted."),
"zvirata-03": ("How many kilograms did the heart of a blue whale stranded on the North Atlantic coast weigh – the largest heart ever weighed in any animal?", "kilogram|kilograms", "The heart of a blue whale stranded in the North Atlantic weighed 180 kilograms – about as much as two adult humans. No other known animal has a bigger one.", "Heart of a stranded North Atlantic individual, 180 kg (400 lb)."),
"zvirata-04": ("How many eggs did a record White Leghorn hen lay in 364 days in an official test at the University of Missouri that ended in August 1979?", "egg|eggs", "White Leghorn no. 2988 laid 371 eggs in 364 days in Professor Harold V. Biellier's test, which ended on 29 August 1979 – more than one egg a day on average. Guinness World Records still lists it as the highest authenticated laying rate.", "371 eggs in 364 days, College of Agriculture, University of Missouri, test ended 29 Aug 1979."),
"zvirata-05": ("How many years old was Ming the clam (Arctica islandica), dredged up off Iceland in 2006 – the oldest known individual animal with a precisely determined age?", "year|years", "The Arctica islandica clam dredged up off northern Iceland in 2006 was 507 years old according to scientists. It hatched during the Chinese Ming dynasty – hence the nickname.", "507 years old when caught (2006), species Arctica islandica."),
"zvirata-06": ("In how many hundredths of a second did Sarah the cheetah from Cincinnati Zoo run a record 100 metres on a certified athletics track in 2012?", "hundredth of a second|hundredths of a second", "Eleven-year-old Sarah ran the 100 m in June 2012 in 5.95 seconds – 595 hundredths – and radar clocked her at up to 98 km/h. Usain Bolt with his 9.58 s would only see her tail.", "5.95 s = 595 hundredths of a second; top speed 98 km/h (61 mph)."),
"zvirata-07": ("How many legs does the record female of the millipede Eumillipes persephone from Western Australia have – the leggiest animal ever discovered?", "leg|legs", "Eumillipes persephone was discovered in August 2020 60 metres underground in Western Australia's Eastern Goldfields. The record female has 1,306 legs – the first millipede in the world to truly pass a thousand.", "Paratype female with 1,306 legs, found August 2020; species described in 2021."),
"zvirata-08": ("How many beats per minute was the highest heart rate ever measured in a hummingbird (specifically a blue-throated hummingbird)?", "beat per minute|beats per minute", "A blue-throated hummingbird's heart was measured at 1,260 beats per minute, 21 beats every second; at rest the bird breathes 250 times a minute. A human heart could keep that up for about one song.", "Up to 1,260 bpm measured in a blue-throated hummingbird."),
"zvirata-09": ("To what depth in metres did a Cuvier's beaked whale dive in a record dive recorded off California in 2014 – the deepest ever measured in a mammal?", "metre|metres", "A Cuvier's beaked whale dived to 2,992 metres off the coast of California in 2014 – the deepest dive ever recorded in a mammal. The species also holds the duration record: in 2020 one individual stayed under for 222 minutes.", "Dive of 2,992 m (9,816 ft) recorded off California in 2014."),
"zvirata-10": ("How many kilometres did a record Arctic tern from the Farne Islands fly on its annual round trip to Antarctica, tracked by Newcastle University scientists in 2015–2016?", "kilometre|kilometres", "The Arctic tern weighs just 100 grams yet has the longest migration of any bird. One tracked individual from the Farne Islands flew 96,000 kilometres between Northumberland and the Weddell Sea in Antarctica – more than twice around the world.", "One tracked individual, 96,000 km round trip (Northumberland – Weddell Sea)."),
"zvirata-11": ("How many centimetres long was Medusa the reticulated python, the longest snake ever kept in captivity according to Guinness World Records?", "centimetre|centimetres", "Medusa from Kansas City measured 7.67 metres in 2011 and weighed almost 159 kg. It took fifteen people to hold her for the photo.", "Measured in 2011."),
"zvirata-12": ("How many kilometres did a record bar-tailed godwit fly non-stop from Alaska to Tasmania in 2022?", "kilometre|kilometres", "A young godwit fitted with tag B6 flew for 11 days and 1 hour without a single stop in October 2022, covering at least 13,560 km from Alaska to Tasmania – the longest known non-stop flight by a bird.", "Minimum measured distance, October 2022."),
"zvirata-13": ("To what depth in metres did a record emperor penguin dive in a dive recorded in 1994?", "metre|metres", "An emperor penguin from the Auster colony dived to 564 metres in 1994 and stayed under for almost 22 minutes – no other bird comes close.", ""),
"zvirata-14": ("How many hearts does an octopus have?", "heart|hearts", "An octopus has three hearts: one main heart and two that pump blood through the gills. Its blood is blue, too, because it carries oxygen with copper instead of iron.", ""),
"zvirata-15": ("How old was Cookie the cockatoo from Brookfield Zoo, the oldest known parrot, when he died?", "year|years", "Cookie the cockatoo lived at the zoo near Chicago from 1934 and died in 2016 aged 83. He outlived several generations of keepers.", ""),
}
